import{_ as n,o as t,c as r,a3 as a}from"./chunks/framework.z_KJ15Ep.js";const f=JSON.parse('{"title":"Schülerdaten erfassen und pflegen","description":"","frontmatter":{},"headers":[],"relativePath":"schild3/schueler.md","filePath":"schild3/schueler.md"}'),d={name:"schild3/schueler.md"};function h(u,e,l,s,i,c){return t(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="schulerdaten-erfassen-und-pflegen" tabindex="-1">Schülerdaten erfassen und pflegen <a class="header-anchor" href="#schulerdaten-erfassen-und-pflegen" aria-label="Permalink to &quot;Schülerdaten erfassen und pflegen&quot;">​</a></h1><p>Pflegen Sie die persönlichen Daten und die schulische Geschichte eines Schulkindes. Wählen Sie zuerst den Datensatz aus; lernabschnittsbezogene Angaben stehen im eigenen Bereich <a href="/schild3/lernabschnitte.html">Lernabschnitte und Leistungen</a>.</p><h2 id="einen-datensatz-anlegen-und-bearbeiten" tabindex="-1">Einen Datensatz anlegen und bearbeiten <a class="header-anchor" href="#einen-datensatz-anlegen-und-bearbeiten" aria-label="Permalink to &quot;Einen Datensatz anlegen und bearbeiten&quot;">​</a></h2><p>Die Anleitung <a href="/einstieg/erste-schritte/neuaufnahmen-in-schild-nrw-tutorial.html">Neue Schülerinnen und Schüler aufnehmen</a> gehört zu diesem Bereich und führt durch die Aufnahme im laufenden oder kommenden Schuljahr. Das <a href="/schild3/schueler/menueband-schueler.html">Menüband</a> bündelt Bearbeitung, Suche und Filter.</p><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Namen, Anschrift und persönliche Basisdaten pflegen</td><td><a href="/schild3/schueler/individualdaten-i-schueler.html">Individualdaten I</a></td></tr><tr><td>Einwanderungsgeschichte, Förderung und Merkmale erfassen</td><td><a href="/schild3/schueler/individualdaten-ii-schueler.html">Individualdaten II</a></td></tr><tr><td>Erziehungsberechtigte und Kontakte pflegen</td><td><a href="/schild3/schueler/erz-berechtigte-telefonnummern-schueler.html">Erziehungsberechtigte</a></td></tr><tr><td>Betriebe und weitere Kontaktadressen zuordnen</td><td><a href="/schild3/schueler/weitere-adressen-schueler.html">Weitere Adressen</a></td></tr></tbody></table><h2 id="schulbesuch-und-besondere-situationen-erfassen" tabindex="-1">Schulbesuch und besondere Situationen erfassen <a class="header-anchor" href="#schulbesuch-und-besondere-situationen-erfassen" aria-label="Permalink to &quot;Schulbesuch und besondere Situationen erfassen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Bisherige Schulen und Schulwechsel dokumentieren</td><td><a href="/schild3/schueler/schulbesuch-schueler.html">Schulbesuch und Schulwechsel</a></td></tr><tr><td>Grundschulnoten und weitere Herkunftsangaben erfassen</td><td><a href="/schild3/schueler/grundschuldaten-eingeben-schueler-schulbesuch.html">Grundschuldaten</a></td></tr><tr><td>Geflüchtete Kinder aufnehmen und zuordnen</td><td><a href="/schild3/schueler/eingabe-von-fluechtlingskindern-tutorial.html">Geflüchtete Kinder erfassen</a></td></tr><tr><td>Ganztag und Betreuung eintragen</td><td><a href="/schild3/schueler/eintragung-der-schueler-im-offenen-ganztag-tutorial.html">Ganztag und Betreuung</a></td></tr><tr><td>Förderbedarf und Vereinbarungen dokumentieren</td><td><a href="/schild3/schueler/foerdermassnahmen-schueler.html">Fördermaßnahmen</a></td></tr></tbody></table><h2 id="erganzende-angaben-pflegen" tabindex="-1">Ergänzende Angaben pflegen <a class="header-anchor" href="#erganzende-angaben-pflegen" aria-label="Permalink to &quot;Ergänzende Angaben pflegen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Aufgabe</th><th>Anleitung</th></tr></thead><tbody><tr><td>Abfrage und Zustimmung dokumentieren</td><td><a href="/schild3/schueler/einwilligung-schueler.html">Einwilligungen</a></td></tr><tr><td>Vermerke mit Art und Datum erfassen</td><td><a href="/schild3/schueler/vermerke-schueler.html">Vermerke</a></td></tr><tr><td>Berufliche Orientierung dokumentieren</td><td><a href="/schild3/schueler/kaoa-schueler.html">KAoA</a></td></tr><tr><td>Funktionen über Personengruppen zuordnen</td><td><a href="/schild3/schueler/erzieher-mit-funktionen-tutorial.html">Funktionen der Erziehungsberechtigten</a></td></tr><tr><td>Erzeugte Dokumente ablegen und aufrufen</td><td><a href="/schild3/schueler/dokumentenverwaltung-schueler.html">Dokumentenablage</a></td></tr></tbody></table><p>Jahrgang und EP-Jahr werden getrennt geführt; die aktuelle Zuordnung pflegen Sie im <a href="/schild3/schueler/aktuelles-halbjahr-aktueller-abschnitt-schueler.html">Lernabschnitt</a>. Bei Einwilligungen unterscheiden Sie Abfrage, dokumentierte Zustimmung und den zugehörigen Nachweis.</p><p>Das <a href="/administration/datenschutz.html">Löschen und Wiederherstellen</a> ist von der laufenden Bearbeitung getrennt beschrieben.</p>',11)])])}const o=n(d,[["render",h]]);export{f as __pageData,o as default};
